도록 시스템을 구축하겠다는 입장을 밝혔다. 그는 "덕소와 와부 지역이 성장 잠재력이 높지만 교통 인프라 부족으로 발전이 제한되어 왔다"며, "철도 교통의 대전환을 통해 시민 삶의 질을 높이고 지역 발전을 이끌겠다"고 강조했다. $(function() { const copyUrlOptions=document.querySelectorAll(".urlBtns, .sns_clipboard"); // 주소복사 이벤트 (v11-fl-v2 수정) copyUrlOptions.forEach(selector=>{ selector.addEventListener("click", (e)=>{ const target=e.target, targetBtn=target.closest("[data-clipboard-text]"); if (targetBtn===null) return; const url=targetBtn.getAttribute("data-clipboard-text")||""; Util.copyToClipboardToast(selector, '', url); }); }); // 사진 lightBox 이벤트 if (typeof ImageViewer != "undefined") { new ImageViewer(".photo-layout", 0); } }); 저작권자 © 한강타임즈 무단전재 및 재배포, AI학습 및 활용 금지 윤종철 기자 todaynt@naver.com 정치/행정부 다른기사 보기 정원오·유보화, 금남시장 찾아 현안 현장소통... 5대 건의사항 전달
